/bin/bash -lc "cat <<'EOF' > middleware.ts
import { NextRequest, NextResponse } from \"next/server\";

export function middleware(request: NextRequest) {
  const { method, nextUrl, headers } = request;
  const ip = request.ip ?? headers.get(\"x-forwarded-for\") ?? \"unknown\";
  const url = "'`${nextUrl.pathname}${nextUrl.search}`;

  console.log(`[request] ${method} ${url} ip=${ip}`);

  return NextResponse.next();
}

export const config = {
  matcher: ["/:path*", "/_next/:path*"],
};
EOF'

